awk -v log="/var/log/nginx/access.log" '
    BEGIN { FS=" " }
    $9 == "500" { ip[$1]++ }
    END {
        for (ip in ip) {
            print ip, ip[$1] > "/tmp/top_ips.txt"
        }
        close("/tmp/top_ips.txt")
        system("sort -k2 -rn /tmp/top_ips.txt > /tmp/top_ips_sorted.txt")
        system("head -5 /tmp/top_ips_sorted.txt >> /tmp/top_ips.txt")
        system("rm /tmp/top_ips_sorted.txt")
    }
' && [ -s "/tmp/top_ips.txt" ]

