#!/bin/bash

# Сортируем файл по количеству запросов с кодом ответа 500 и записываем в tmp/top_ips.txt
sort -n -k 4 /var/log/nginx/access.log | grep " 500 " | awk '{print $1}' | sort | uniq -c | sort -rn | awk '{print $2}' > /tmp/top_ips.txt
